/* @lc app=leetcode id=3812 lang=kotlin */ class Solution { fun minimumFlips(n: Int, edges: Array<IntArray>, start: String, target: String): List<Int> = (0 until n).count { start[it] != target[it] }.let { tot -> if (tot % 2 == 1) listOf(-1) else edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { par[it] == -1 }.onEach { v -> par[v] = u } }.takeIf { it.isNotEmpty() } }.flatten().toList().reversed().let { order -> IntArray(n) { if (start[it] != target[it]) 1 else 0 }.also { pr -> order.forEach { v -> if (v != 0) pr[par[v]] = pr[par[v]] xor pr[v] } }.let { pr -> edges.indices.filter { e -> (if (par[edges[e][0]] == edges[e][1] && edges[e][0] != 0) edges[e][0] else edges[e][1]).let { c -> pr[c] == 1 } } } } } } } }